import snapshot from "./comuni.json";
import type { ComuneData, ComuniSnapshot } from "./types";

/*
 * Build-time snapshot generated by scripts/snapshot.mjs from the Cruscotto
 * Italia dashboard. No runtime fetch, no personal data, no tracking.
 */
const data = snapshot as unknown as ComuniSnapshot;

export const SNAPSHOT_META = data.meta;
export const COMUNI: ComuneData[] = data.comuni;
export const PILOT_ID = "034014";

export function getComune(id: string): ComuneData | undefined {
  return COMUNI.find((comune) => comune.identity.istat === id);
}

export function pilot(): ComuneData {
  return getComune(PILOT_ID) ?? COMUNI[0];
}
